   165	  for (const item of items) {
   166	    for (const slug of (item as LoadedSpecItem).slugs || []) {
   167	      existingSpecRefs.add(slug);
   168	    }
   169	    existingSpecRefs.add(refIndex.shortUlid(item._ulid));
   170	  }
   171	
   172	  // Resolve module reference
   173	  const moduleResult = refIndex.resolve(options.module);
   174	  if (!moduleResult.ok) {
   175	    error(errors.reference.itemNotFound(options.module));
   176	    process.exit(EXIT_CODES.NOT_FOUND);
